// --- Issue #1: the ball plows through bricks instead of bouncing -----------
// Each case below was added FIRST as a red test (the ball just destroyed the
// brick without any deflection), then made green by the bounce fix in
// `frame()`. A fake 2d context swallows the drawing calls: we observe the
// game state, not the pixels.

function fakeCtx() {
  const noop = () => {};
  return {
    fillRect: noop,
    beginPath: noop,
    arc: noop,
    fill: noop,
    fillText: noop,
  };
}

function oneBrick() {
  return [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
}

// Per face: only the axis of the smaller penetration is flipped, the other
// component is left exactly as it was.
test('#1 side hit (left face): vx flips, vy untouched', () => {
  const state = createState(1);
  state.bricks = oneBrick();
  state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };

  frame(fakeCtx(), state);

  assert.equal(state.ball.vx, -300);
  assert.equal(state.ball.vy, 30);
  assert.equal(state.ball.x + BALL_R, 100, 'ball pushed out to the left face');
});

test('#1 side hit (right face): vx flips, vy untouched', () => {
  const state = createState(1);
  state.bricks = oneBrick();
  state.ball = { x: 176, y: 110, r: BALL_R, vx: -300, vy: 30 };

  frame(fakeCtx(), state);

  assert.equal(state.ball.vx, 300);
  assert.equal(state.ball.vy, 30);
  assert.equal(state.ball.x - BALL_R, 172, 'ball pushed out to the right face');
});

test('#1 top hit: vy flips, vx untouched', () => {
  const state = createState(1);
  state.bricks = oneBrick();
  state.ball = { x: 136, y: 96, r: BALL_R, vx: 30, vy: 300 };

  frame(fakeCtx(), state);

  assert.equal(state.ball.vy, -300);
  assert.equal(state.ball.vx, 30);
  assert.equal(state.ball.y + BALL_R, 100, 'ball pushed out above the top face');
});

test('#1 bottom hit: vy flips, vx untouched', () => {
  const state = createState(1);
  state.bricks = oneBrick();
  state.ball = { x: 136, y: 124, r: BALL_R, vx: 30, vy: -300 };

  frame(fakeCtx(), state);

  assert.equal(state.ball.vy, 300);
  assert.equal(state.ball.vx, 30);
  assert.equal(state.ball.y - BALL_R, 120, 'ball pushed out below the bottom face');
});

// Corner: equal penetration on both axes is a diagonal hit — both components
// flip, and the ball is pushed out of the corner.
test('#1 corner hit: both components flip', () => {
  const state = createState(1);
  state.bricks = oneBrick();
  state.ball = { x: 96, y: 96, r: BALL_R, vx: 300, vy: 300 };

  frame(fakeCtx(), state);

  assert.equal(state.ball.vx, -300);
  assert.equal(state.ball.vy, -300);
  assert.equal(state.ball.x + BALL_R, 100);
  assert.equal(state.ball.y + BALL_R, 100);
});

// Neighbours: the 8 px grid gap is narrower than the 14 px ball, so a seam
// overlaps two bricks in the SAME pass. The bounce must apply exactly once
// (vy = -vy twice cancels out) and both bricks die, like a real arcade game.
test('#1 seam (side by side): single bounce, both bricks broken', () => {
  const state = createState(1);
  state.bricks = [
    { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 },
    { x: 100 + BRICK_W + BRICK_GAP, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 },
  ];
  state.ball = { x: 176, y: 126, r: BALL_R, vx: 6, vy: -60 };

  frame(fakeCtx(), state);

  assert.equal(state.ball.vy, 60, 'vy flipped exactly once');
  assert.equal(state.ball.vx, 6, 'vx untouched');
  assert.ok(state.bricks.every((b) => !b.alive), 'seam hit breaks both bricks');
});

test('#1 seam (stacked): single bounce, both bricks broken', () => {
  const state = createState(1);
  state.bricks = [
    { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 },
    { x: 100, y: 100 + BRICK_H + BRICK_GAP, w: BRICK_W, h: BRICK_H, row: 1, alive: true, points: 10 },
  ];
  state.ball = { x: 94, y: 124, r: BALL_R, vx: 60, vy: 6 };

  frame(fakeCtx(), state);

  assert.equal(state.ball.vx, -60, 'vx flipped exactly once');
  assert.equal(state.ball.vy, 6, 'vy untouched');
  assert.ok(state.bricks.every((b) => !b.alive), 'seam hit breaks both bricks');
});

// Tunnelling: at level 6 the per-frame displacement (35.5 px) is larger than
// the 34 px needed to cross a brick (BRICK_H + diameter). Discrete detection
// never sees the overlap — the fix must sweep between the two positions.
test('#1 fast ball: swept across the brick, not through it', () => {
  const state = createState(6);
  const brick = { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 };
  state.bricks = [brick];
  state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };

  // Same order as boot(): step moves the ball, then frame() judges the sweep.
  step(state, 0.05);
  frame(fakeCtx(), state);

  assert.equal(brick.alive, false, 'the brick must not be skipped');
  assert.ok(state.ball.vy > 0, 'the ball bounces back down');
  assert.ok(state.ball.y + BALL_R <= 120, 'ball ends up outside the brick');
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

