// --- Brick bounce (issue #1) -----------------------------------------------

// Tolerance for comparing penetrations: below this, the two axes are
// considered equally penetrated (a corner hit).
const PEN_EPS = 1e-9;

// Overlap depth on the x and y axes (ball box vs brick box). Always >= 0.
function penetration(ball, brick) {
  const penX =
    Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const penY =
    Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
  return { penX: Math.max(0, penX), penY: Math.max(0, penY) };
}

// Reposition the ball so it no longer overlaps the brick along x.
// If the centre is inside the brick's span, push it out the nearer side.
function pushOutX(ball, brick) {
  if (ball.x < brick.x) ball.x = brick.x - ball.r;
  else if (ball.x > brick.x + brick.w) ball.x = brick.x + brick.w + ball.r;
  else ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
}

// Same as pushOutX, along y.
function pushOutY(ball, brick) {
  if (ball.y < brick.y) ball.y = brick.y - ball.r;
  else if (ball.y > brick.y + brick.h) ball.y = brick.y + brick.h + ball.r;
  else ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
}

// Bounce the ball off the brick. The face hit is the axis with the smaller
// penetration: flip that component only and push the ball back out; equal
// penetration on both axes means a corner hit, so flip both.
function bounceBall(ball, brick) {
  const { penX, penY } = penetration(ball, brick);

  if (Math.abs(penX - penY) <= PEN_EPS) {
    // Corner: diagonal hit, flip both components.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    pushOutX(ball, brick);
    pushOutY(ball, brick);
  } else if (penX < penY) {
    // Side hit: flip horizontal, leave vertical exactly as it was.
    ball.vx = -ball.vx;
    pushOutX(ball, brick);
  } else {
    // Top/bottom hit: flip vertical, leave horizontal exactly as it was.
    ball.vy = -ball.vy;
    pushOutY(ball, brick);
  }
}

// Entry parameter t in [0,1] where the segment (px,py)->(x,y), swept with the
// ball's radius, first touches the brick — or null if it never does. The
// moving circle hits the brick iff the segment crosses the brick expanded by
// the radius (Liang-Barsky slab test).
function sweptEntry(px, py, x, y, r, brick) {
  const xmin = brick.x - r;
  const xmax = brick.x + brick.w + r;
  const ymin = brick.y - r;
  const ymax = brick.y + brick.h + r;
  const dx = x - px;
  const dy = y - py;
  let t0 = 0;
  let t1 = 1;

  if (dx === 0) {
    if (px < xmin || px > xmax) return null;
  } else {
    let a = (xmin - px) / dx;
    let b = (xmax - px) / dx;
    if (a > b) [a, b] = [b, a];
    if (a > t1 || b < t0) return null;
    t0 = Math.max(t0, a);
    t1 = Math.min(t1, b);
  }

  if (dy === 0) {
    if (py < ymin || py > ymax) return null;
  } else {
    let a = (ymin - py) / dy;
    let b = (ymax - py) / dy;
    if (a > b) [a, b] = [b, a];
    if (a > t1 || b < t0) return null;
    t0 = Math.max(t0, a);
    t1 = Math.min(t1, b);
  }

  return t0 <= t1 ? t0 : null;
}

// Where did the ball meet the brick? Either it overlaps it right now (use the
// current position), or it crossed it during the last step (sweep from the
// previous position; return the point of first contact). Null = no contact.
function contactPoint(ball, brick) {
  if (collides(ball, brick)) return { x: ball.x, y: ball.y };

  const px = ball.px;
  const py = ball.py;
  if (px === undefined || py === undefined || (px === ball.x && py === ball.y)) return null;

  const t = sweptEntry(px, py, ball.x, ball.y, ball.r, brick);
  if (t === null) return null;
  return { x: px + (ball.x - px) * t, y: py + (ball.y - py) * t };
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the step started: the next brick pass sweeps between this
  // position and the new one so a fast ball cannot tunnel through a brick.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;

