// Bricks: collide + bounce + score in one place, then draw. The ball is
// resolved against every brick it touches (a seam overlaps two at once) but
// the bounce itself is applied at most once per pass.
const ball = state.ball;
const vx0 = ball.vx;
const vy0 = ball.vy;
let first = null;

for (const brick of state.bricks) {
  if (!brick.alive) continue;

  const contact = contactPoint(ball, brick);
  if (!contact) continue;

  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
  if (!first) first = { brick, contact };
}

// Apply the deflection once, from the first brick the ball met. The ball is
// placed at the contact point (only a swept hit moves it) so the face and
// the push-out are computed on the geometry that was actually crossed, and
// so it never overlaps again on the next frame (no sticky bounce).
if (first) {
  ball.x = first.contact.x;
  ball.y = first.contact.y;
  if (ball.vx === vx0 && ball.vy === vy0) bounceBall(ball, first.brick);
}

for (const brick of state.bricks) {
  if (!brick.alive) continue;
  ctx.fillStyle = brickColor(brick.row);
  ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
}

